  "/evenements": { nom: "evenements-kiosque", y: 57 },
  "/emploi": { nom: "emploi-metiers-reunion", y: 45 },
  "/mer": { nom: "mer-lagon-ermitage", y: 60 },
  "/vigilance": { nom: "cyclone-saison-ciel", y: 31 },
  "/crues": { nom: "crues-radier-ravine", y: 100 },
  "/historique": { nom: "historique-abri-meteo", y: 39 },
  "/cyclones": { nom: "cyclone-saison-ciel", y: 31 },
  "/volcan": { nom: "volcan-repos-bellecombe", y: 51 },
  "/velos": { nom: "velos-front-de-mer", y: 64 },
  "/bornes": { nom: "bornes-parking-palmiers", y: 64 },
  "/coupures-eau": { nom: "coupures-eau-chateau", y: 44 },
  "/defibrillateurs": { nom: "defibrillateur-mairie", y: 74 },
  "/secheresse": { nom: "fond-secheresse-ravine", y: 44 },
  "/sport": { nom: "sport-stade-montagnes", y: 61 },
  "/enfants": { nom: "enfants-aire-de-jeux-haut", y: 74 },
  "/eau": { nom: "eau-bassin-ravine", y: 77 },
  "/air": { nom: "air-cote-ouest", y: 56 },
  "/electricite": { nom: "electricite-barrage-toits", y: 56 },
  "/calendrier": { nom: "calendrier-lever-est", y: 69 },
  "/bus": { nom: "car-jaune-haut-sans-embleme", y: 41 },
  // The list only: a commune's own page shows one place, which has no picture of its own yet.
  "/communes": { nom: "communes-ville-creole", y: 56 },
  // Off the menu.
  "/carburants": { nom: "carburants-station-hauts", y: 77 },
  "/collecte": { nom: "collecte-rue-ouest", y: 100 },
  "/feux": { nom: "fond-feux-hauts", y: 51 },
  "/sentiers": { nom: "sentier-foret-hauts", y: 82 },
  "/decheteries": { nom: "decheterie-ouest", y: 72 },
  "/baignade": { nom: "baignade-lagon-sud", y: 46 },
