  "/alerte-cyclone": { nom: "cyclone-saison-ciel", y: 31 },
  "/ecoles-cyclone": { nom: "cyclone-saison-ciel", y: 31 },
  "/evenements/ce-week-end": { nom: "evenements-kiosque", y: 57 },
  "/evenements/concerts": { nom: "evenements-kiosque", y: 57 },
