/**
 * The pages left without a picture, and why: each section of the menu (categories.ts) and each page of the sitemap has
 * one or a reason here (`/*`: the pages below an address). The page of one place or one event (a station, a commune, a
 * bus stop, a past cyclone, a proposed event) has none while it has no picture of its own: a calm sky above a past
 * cyclone would pass for its photo.
 */
export const SANS_FOND: Record<string, string> = {
  "/": "the home page shows the news of the moment at once",
  "/actualites": "a picture there would pass for the photo of one of the day's news",
  "/chiffres": "about the site itself, which has no place to show",
  "/a-propos": "about the site itself, which has no place to show",
  "/valeurs": "about the site itself, which has no place to show",
  "/presse": "about the site itself, which has no place to show",
  "/nouveautes": "about the site itself, which has no place to show",
  "/publier": "about the site itself, which has no place to show",
  "/ouvrir-ses-donnees": "about the site itself, which has no place to show",
  "/sites-sans-reponse": "about the site itself, which has no place to show",
  "/conditions": "a legal text",
  "/confidentialite": "a legal text",
  "/hors-ligne": "the page of a phone without network",
  "/antennes": "the relief map of the whole island is the page itself; a photo above it would show one place only",
  "/communes/*": "the page of one place",
  "/aujourdhui/*": "the page of one place",
  "/meteo/*": "the page of one place",
  "/coupures-eau/*": "the page of one place",
  "/enfants/*": "the page of one place",
  "/collecte/*": "the page of one place",
  "/bus/arret/*": "the page of one place",
  "/sentiers/*": "the page of one place",
  "/randonnees/*": "the page of one place",
  "/cyclones/*": "the page of one past cyclone",
};

/** The pages whose picture is shown only while their own data says all is green: a calm sky above a storm would contradict it. */
const SEULEMENT_VERT = new Set(["/vigilance", "/cyclones", "/crues"]);

/**
 * Behind the band's text, over its upper 220 px (300 on wide screens), never adding height: framed on its upper third
 * on a phone, on its subject on wider screens, faded out by a mask, which works on any background. Dimmed so that the
 * band's light text keeps a contrast of at least 4.5:1 where the picture is brightest; more so under the top 3 rem, where
 * the breadcrumb's small grey text and the mention sit. The mention at the top right, like a photo credit, in the band's
 * brightest text. Not printed.
 */
export const FOND_CSS = `
.band>.fond{position:absolute;top:0;left:0;width:100%;height:220px;object-fit:cover;object-position:50% 25%;opacity:.35;pointer-events:none;
-webkit-mask-image:linear-gradient(to bottom,rgb(0 0 0/.6) 0,rgb(0 0 0/.6) 3rem,#000 5.5rem,rgb(0 0 0/.55) 45%,transparent 100%);mask-image:linear-gradient(to bottom,rgb(0 0 0/.6) 0,rgb(0 0 0/.6) 3rem,#000 5.5rem,rgb(0 0 0/.55) 45%,transparent 100%)}
@media (min-width:48rem){.band>.fond{height:300px;object-position:50% var(--y)}}
.fond-ia{position:absolute;top:.4rem;right:16px;margin:0;font-size:12px;line-height:1.2;color:var(--on-night)}
@media print{.band>.fond,.fond-ia{display:none}}
`.replace(/\n/g, "");

/** The brand kit's words, beside every picture made by AI. */
export const MENTION = "Illustration générée par IA";

const sansFond = new AsyncLocalStorage<boolean>();

/** Runs `fn` with the pages it builds left without their picture when `request` asks to save data. */
export const withSaveData = <T>(request: Request, fn: () => T): T => sansFond.run(request.headers.get("save-data")?.trim().toLowerCase() === "on", fn);

/** Whether the vigilance or the volcano rules out every picture: orange or red, any cyclone alert, the volcano's alert. */
export const enAlerte = (alerte: Alerte | undefined, volcan: boolean): boolean => volcan || (!!alerte && ("cyclone" in alerte.court || alerte.couleur >= 3));

/**
 * The picture behind the band of the page at `path` and its mention, or nothing. On a phone, half its definition: the
 * picture is faded and dimmed, and the lighter file leaves the page's stylesheet and font their bandwidth. `vert`: the
 * page's own data says all is green (the pages of SEULEMENT_VERT).
 */
export function fond(path: string, alerte: Alerte | undefined, volcan: boolean, vert = false): string {
  const fond = FONDS[path];
  if (!fond || sansFond.getStore() || enAlerte(alerte, volcan) || (SEULEMENT_VERT.has(path) && !vert)) return "";
  const f = files[fond.nom];
  return `<img class="fond" style="--y:${fond.y}%" src="/fonds/${f["480"]}" srcset="/fonds/${f["480"]} 480w, /fonds/${f["1024"]} 1024w" sizes="(min-width: 48rem) 100vw, 50vw" alt="" decoding="async" fetchpriority="low"><p class="fond-ia">${MENTION}</p>`;
}
